//! Vectors for `blocks/iop/tensor.h`, generated by
//! `scripts/cpp_vectors/tensor_vectors.cpp`.

use std::collections::HashMap;
use std::rc::Rc;

use fp_core::field::ext::{F, E};
use fp_core::iop::tensor::{Form, Tensor};

const VECTORS: &str = include_str!("../../fixtures/tensor_vectors.txt");

fn ev(s: u64, i: u32) -> E {
    E([
        F(s * 101 + i as u64 * 3 + 1),
        F(s * 211 + i as u64 * 5 + 2),
        F(s * 307 + i as u64 * 7 + 3),
    ])
}
fn fv(s: u64, i: u32) -> F {
    F(s * 401 + i as u64 * 11 + 1)
}
fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}
fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([
        F(u64::from_str_radix(p[0], 16).unwrap()),
        F(u64::from_str_radix(p[1], 16).unwrap()),
        F(u64::from_str_radix(p[2], 16).unwrap()),
    ])
}
fn es(s: &str) -> Vec<E> {
    if s == "-" {
        return Vec::new();
    }
    s.split(';').map(e).collect()
}
fn hex(s: &str) -> u64 {
    u64::from_str_radix(s, 16).unwrap()
}

fn summary(id: &str, t: &Tensor, kv: &HashMap<&str, &str>) {
    assert_eq!(t.vars(), kv["vars"].parse::<u32>().unwrap(), "vars {}", id);
    assert_eq!(t.scalar, e(kv["scalar"]), "scalar {}", id);
    assert_eq!(t.pick_mask(), hex(kv["pick_mask"]), "pick mask {}", id);
    assert_eq!(t.pick_value(), hex(kv["pick_value"]), "pick value {}", id);
    let mut pairs = Vec::new();
    for i in 0..t.vars() {
        if !t.picks(i) {
            pairs.push(t.lo(i));
            pairs.push(t.hi(i));
        }
    }
    assert_eq!(pairs, es(kv["pairs"]), "pairs {}", id);
    let dense: Vec<u32> = if kv["dense"] == "-" {
        Vec::new()
    } else {
        kv["dense"].split(',').map(|x| x.parse().unwrap()).collect()
    };
    assert_eq!(t.dense_vars, dense, "dense {}", id);
    assert_eq!(t.first, kv["first"].parse::<u64>().unwrap(), "first {}", id);
    assert_eq!(
        t.values.as_ref().map_or(0, |v| v.len()),
        kv["values"].parse::<usize>().unwrap(),
        "values {}",
        id
    );
}

#[test]
fn tensor_vectors_match_the_cpp_reference() {
    let z1 = [ev(1, 0), ev(1, 1), ev(1, 2)];
    let mut t0 = Tensor::eq(&z1, 3, ev(2, 0));
    let mut t0f = t0.clone();
    t0f.fix_low(&[ev(3, 0), ev(3, 1), ev(3, 2)], 1);
    let mut t0f2 = t0.clone();
    t0f2.fix_low(&[ev(3, 0), ev(3, 1), ev(3, 2)], 2);
    let _ = &mut t0;

    let f4 = [fv(4, 0), fv(4, 1), fv(4, 2)];
    let t1 = Tensor::product(&f4, 3, ev(2, 1));

    let mut t2 = Tensor::default();
    t2.scalar = ev(6, 0);
    t2.push(ev(6, 1), ev(6, 2));
    t2.push(E::zero(), E::one());
    t2.push(E::one(), E::zero());
    let mut t2s = t2.clone();
    t2s.set_pair(0, ev(6, 3), ev(6, 4));
    let mut t2r = t2s.clone();
    t2r.rotate(1);
    let mut t2i = t2r.clone();
    t2i.insert_choice(1, 2, 3);

    let mut t3 = Tensor::default();
    t3.scalar = ev(7, 0);
    t3.push(ev(7, 1), ev(7, 2));
    t3.push_dense(2);
    t3.set_values(Rc::new(vec![ev(8, 0), ev(8, 1), ev(8, 2), ev(8, 3)]), 0);
    let g10 = [ev(10, 0), ev(10, 1), ev(10, 2)];
    let mut t3f1 = t3.clone();
    t3f1.fix_low(&g10, 1);
    let mut t3f2 = t3.clone();
    t3f2.fix_low(&g10, 2);

    let mut t3b = Tensor::default();
    t3b.scalar = ev(11, 0);
    t3b.push_dense(1);
    t3b.push(ev(11, 1), ev(11, 2));
    t3b.set_values(Rc::new(vec![ev(12, 0), ev(12, 1)]), 0);
    let mut t3bf = t3b.clone();
    t3bf.fix_low(&g10, 2);

    let z13 = [ev(13, 0), ev(13, 1)];
    let pf14 = [fv(14, 0), fv(14, 1)];
    let mut f0 = Form::default();
    f0.push_tensor(Tensor::eq(&z13, 2, ev(15, 0)));
    f0.push_tensor(Tensor::product(&pf14, 2, ev(15, 1)));
    f0.add_entry(0, ev(15, 2));
    f0.add_entry(0, ev(15, 3));
    f0.add_entry(3, ev(15, 4));
    let mut f1 = f0.clone();
    {
        let mut g = Form::default();
        g.add_entry(1, ev(16, 0));
        g.scale(ev(16, 1));
        f1.add_ref(&g, ev(16, 2));
    }
    let mut f2 = f1.clone();
    f2.fix_low(&[ev(17, 0)], 1, ev(17, 1));

    let z18 = [ev(18, 0), ev(18, 1)];
    let mut f3 = Form::default();
    f3.push_tensor(Tensor::eq(&z18, 2, ev(19, 0)));
    f3.add_entry(2, ev(19, 1));
    f3.freeze(2);
    let f3l = f3.flattened();
    let mut f4 = f3.clone();
    f4.fix_low(&[ev(20, 0), ev(20, 1)], 1, ev(20, 2));

    let mut f5 = Form::default();
    f5.push_tensor(Tensor::eq(&z18, 2, ev(21, 0)));
    f5.add_entry(2, ev(21, 1));
    f5.freeze(2);
    f5.insert_choice(0, 1, 0);
    let mut f6 = f5.clone();
    f6.fix_low(&[ev(22, 0), ev(22, 1), ev(22, 2)], 1, ev(22, 3));

    let mut tensors: HashMap<&str, Tensor> = HashMap::new();
    for (id, t) in [
        ("T0", &t0),
        ("T0F", &t0f),
        ("T0F2", &t0f2),
        ("T1", &t1),
        ("T2", &t2),
        ("T2S", &t2s),
        ("T2R", &t2r),
        ("T2I", &t2i),
        ("T3", &t3),
        ("T3F1", &t3f1),
        ("T3F2", &t3f2),
        ("T3b", &t3b),
        ("T3bF", &t3bf),
    ] {
        tensors.insert(id, t.clone());
    }
    let mut forms: HashMap<&str, Form> = HashMap::new();
    for (id, f) in [
        ("F0", &f0),
        ("F1", &f1),
        ("F2", &f2),
        ("F3", &f3),
        ("F3L", &f3l),
        ("F4", &f4),
        ("F5", &f5),
        ("F6", &f6),
    ] {
        forms.insert(id, f.clone());
    }

    let mut lines = 0usize;
    for line in VECTORS.lines() {
        lines += 1;
        let tag = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        match tag {
            "T" => summary(kv["id"], &tensors[kv["id"]], &kv),
            "AT" => {
                let t = &tensors[kv["id"]];
                let j: u64 = kv["j"].parse().unwrap();
                assert_eq!(t.at(j), e(kv["v"]), "at line {}", lines);
            }
            "MLE" => {
                let got = match kv["id"] {
                    "T0" => tensors["T0"].mle(&z1),
                    "T1" => tensors["T1"].mle(&[ev(5, 0), ev(5, 1), ev(5, 2)]),
                    "T3" => tensors["T3"].mle(&[ev(9, 0), ev(9, 1), ev(9, 2)]),
                    "F0" => forms["F0"].mle(&z13, 2),
                    other => panic!("line {}: MLE id {}", lines, other),
                };
                assert_eq!(got, e(kv["v"]), "mle line {}", lines);
            }
            "PART" => {
                let t = &tensors[kv["id"]];
                let v = t.part(kv["from"].parse().unwrap(), kv["count"].parse().unwrap());
                assert_eq!(v, es(kv["v"]), "part line {}", lines);
            }
            "ADD" => {
                let t = &tensors[kv["id"]];
                let want = es(kv["out"]);
                let mut got = vec![E::zero(); want.len()];
                t.add_to_simple(&mut got);
                assert_eq!(got, want, "add line {}", lines);
            }
            "FOLDED" => {
                let t = &tensors[kv["id"]];
                let count: u32 = kv["count"].parse().unwrap();
                let s = t.folded_slice(&g10, count);
                assert_eq!(**s.values.as_ref().unwrap(), es(kv["values"]), "folded values line {}", lines);
                assert_eq!(s.factor, e(kv["factor"]), "folded factor line {}", lines);
            }
            "FORM" => {
                let f = &forms[kv["id"]];
                assert_eq!(f.tensors.len(), kv["ntensors"].parse::<usize>().unwrap());
                assert_eq!(f.entries.len(), kv["nentries"].parse::<usize>().unwrap());
                assert_eq!(f.frozen.len(), kv["nfrozen"].parse::<usize>().unwrap());
                assert_eq!(f.empty(), kv["empty"] == "1");
            }
            "FAT" => {
                let f = &forms[kv["id"]];
                let j: u64 = kv["j"].parse().unwrap();
                assert_eq!(f.at(j), e(kv["v"]), "form at line {}", lines);
            }
            "FADD" => {
                let f = &forms[kv["id"]];
                let want = es(kv["out"]);
                let vars = want.len().trailing_zeros();
                let mut got = vec![E::zero(); want.len()];
                f.add_to(&mut got, vars);
                assert_eq!(got, want, "form add line {}", lines);
            }
            other => panic!("line {}: unknown tag {}", lines, other),
        }
    }
    assert!(lines > 100, "fixture too short");
}
